create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.NFMD_PARAMETER (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant ID',
	DWH_CREATED_TMSP TIMESTAMP_NTZ(9) NOT NULL COMMENT 'timestamp when the record was created',
	DISCOUNT_STEPS NUMBER(38,0) COMMENT 'gap between two discounts',
	MIN_DISCOUNT_PCT NUMBER(38,0) COMMENT 'minimum discount percent (0-100)',
	MAX_DISCOUNT_PCT NUMBER(38,0) COMMENT 'maximum discount percent (0-100)',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	MIN_PRICE_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'lowest possible gross price in local currency',
	NO_TOUCH_DAYS_CNT NUMBER(38,0) COMMENT 'No Touch period (no change in price) in number of days.',
	MIN_DAYS_BTW_DISCOUNTS_CNT NUMBER(38,0) COMMENT 'minimum number of days between two discounts',
	MAX_DAYS_BTW_DISCOUNTS_CNT NUMBER(38,0) COMMENT 'maximum number of days between two discounts',
	DISCOUNT_DAY_OF_WEEK VARCHAR(255) COMMENT 'day of the week for the discount',
	VALIDITY_DAYS_CNT NUMBER(38,0) COMMENT 'Number of days for which the discounted price will be valid',
	PRICE_ENDING_THRESHOLD NUMBER(38,0) COMMENT 'if the modelprice is above this value, the model price is rounded',
	MAX_DISCOUNT_FOR_MAX_PRICE_PCT NUMBER(38,0) COMMENT 'Max discount for price X ( in percent 0-100)',
	MAX_PRICE_FOR_MAX_DISCOUNT NUMBER(38,0) COMMENT 'Value X another max discount',
	DISCOUNT_TYPE_FG NUMBER(38,0) COMMENT '0 - Discount can be set in percent, 1 - discount can be set in currency.',
	PROMO_LIFECYCLE_WEEKS_CNT NUMBER(38,0) COMMENT 'The target length of promotion in number of weeks',
	EXPERIMENT_COHORTS_CNT NUMBER(38,0) COMMENT 'how many cohorts does one experiment contains',
	EXPERIMENTS_FOR_MANUAL_EVALUATION_CNT NUMBER(38,0) COMMENT 'how many experiments are included in one manual evaluation cycle',
	SUCCESS_WRITE_OFF_THRESHOLD NUMBER(38,5) COMMENT 'for a successful cohort, how much less write-off should the test group have against control group',
	SUCCESS_COHORTS_THRESHOLD NUMBER(38,0) COMMENT 'for a successful experiment, how many cohorts should the test group outperform control group',
	EXPORT_DAY_OF_WEEK VARCHAR(20) COMMENT 'in which weekday is the data from Snowflake exported to be loaded in operational system',
	APPLY_PRICE_ROUNDING_FG NUMBER(38,0) COMMENT 'Specifies if the prediction model should (or should not) apply rounding to prices',
	FRONTEND_DATA_RETENTION_PERIOD_WEEKS_CNT NUMBER(38,0) COMMENT 'Specified for how many weeks we keep data in tables for frontend (NFMD_ART_PROMOTION, NFMD_ARTICLE_STORE_SCORECARD) so we can compare the results(effect) of past promotions with the current one.',
	SECOND_DISCOUNT_PCT NUMBER(38,0) COMMENT 'Percent by which the price is reduced for the second discount',
	SECOND_DISCOUNT_VALIDITY_WKS_CNT NUMBER(38,0) COMMENT 'Number of weeks for which the price after the second discount will be valid',
	SECOND_DISCOUNT_LIFECYCLE_WEEKS_CNT NUMBER(38,0) COMMENT 'Number of weeks after that the second discount is being calculated',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_NFMD_PARAMETER primary key (MANDANT_ID, DWH_CREATED_TMSP)
)COMMENT='The parameter settings for the model that determines price reduction proposals. These settings are required both in the Fronted and in the AI model for calculating the KPIs'
;
